import 'dart:ui' show PlatformDispatcher;

import 'package:flutter/widgets.dart';

/// The fourteen languages supported by cards are also the languages in which
/// the app can speak to its reader. `auto` follows Android/Windows, while a
/// person who mixes device languages can pin a choice in Settings.
const interfaceLanguages = <String, String>{
  'auto': 'System language',
  'en': 'English',
  'ru': 'Русский',
  'et': 'Eesti',
  'de': 'Deutsch',
  'fr': 'Français',
  'es': 'Español',
  'it': 'Italiano',
  'pt': 'Português',
  'pl': 'Polski',
  'uk': 'Українська',
  'nl': 'Nederlands',
  'tr': 'Türkçe',
  'sv': 'Svenska',
  'fi': 'Suomi',
};

String resolvedInterfaceLanguage(String stored) {
  if (stored != 'auto' && interfaceLanguages.containsKey(stored)) return stored;
  final code = PlatformDispatcher.instance.locale.languageCode.toLowerCase();
  return interfaceLanguages.containsKey(code) && code != 'auto' ? code : 'en';
}

/// Deliberately keyed by the English source phrase. Widgets can translate
/// their labels at the point they render them, which also keeps shared buttons
/// and empty states from drifting into different translations over time.
class AppI18n {
  static String text(BuildContext context, String english) {
    final code = Localizations.localeOf(context).languageCode.toLowerCase();
    return _values[code]?[english] ?? english;
  }

