      'The computer and the browser can sign in with the same Google account themselves. Approving a code here is the other way in: scan or type the eight characters they show.': 'Komputer i przeglądarka mogą samodzielnie logować się przy użyciu tego samego konta Google. Zatwierdzenie kodu odbywa się w inny sposób: zeskanuj lub wpisz osiem wyświetlanych znaków.',
