      'The computer and the browser can sign in with the same Google account themselves. Approving a code here is the other way in: scan or type the eight characters they show.': 'Компьютер и браузер могут сами войти в систему с одной и той же учетной записью Google. Утвердить код можно другим способом: отсканируйте или введите восемь отображаемых символов.',
      'The extension makes web subtitles clickable and saves anything you highlight.': 'Расширение делает веб-субтитры кликабельными и сохраняет все, что вы выделяете.',
      'The games are built from your own library. With \$_minimumPairs words there is enough to play.': 'Игры созданы из вашей собственной библиотеки. С \$_minimumPairs слов хватит, чтобы поиграть.',
