      'The computer and the browser can sign in with the same Google account themselves. Approving a code here is the other way in: scan or type the eight characters they show.': 'Bilgisayar ve tarayıcı aynı Google hesabıyla oturum açabilir. Burada bir kodu onaylamanın diğer yolu da şudur: gösterdikleri sekiz karakteri tarayın veya yazın.',
